package com.parksmart.service;
import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import com.parksmart.config.JwtUtil; import com.parksmart.dto.AuthDtos; import com.parksmart.entity.User; import com.parksmart.exception.ApiException; import com.parksmart.repository.UserRepository; import org.springframework.http.HttpStatus;
@Service public class AuthService { private final UserRepository users; private final PasswordEncoder encoder; private final JwtUtil jwt; private final ClockService clock; public AuthService(UserRepository u,PasswordEncoder e,JwtUtil j,ClockService c){users=u;encoder=e;jwt=j;clock=c;}
 public User register(AuthDtos.Register r){if(users.findByEmailIgnoreCase(r.email).isPresent())throw new ApiException(HttpStatus.CONFLICT,"EMAIL_EXISTS","Email already registered");User user=new User(r.name,r.email.toLowerCase(),encoder.encode(r.password));user.setCreatedAt(clock.now());return users.save(user);}
 public String login(AuthDtos.Login r){User u=users.findByEmailIgnoreCase(r.email).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"INVALID_CREDENTIALS","Invalid email or password"));if(!encoder.matches(r.password,u.getPasswordHash()))throw new ApiException(HttpStatus.UNAUTHORIZED,"INVALID_CREDENTIALS","Invalid email or password");return jwt.generate(u.getEmail());}
 public User current(String email){return users.findByEmailIgnoreCase(email).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"UNAUTHORIZED","User not found"));}}